package com.bankslotlock;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup(BankSlotLockConfig.GROUP)
public interface BankSlotLockConfig extends Config
{
	String GROUP = "bankslotlock";
	/** Per-account (RuneScape profile) key holding the comma-separated locked item IDs. */
	String LOCKED_ITEMS_KEY = "lockedItems";

	@ConfigSection(
		name = "Locked items",
		description = "How locked items behave in the bank.",
		position = 10
	)
	String lockedSection = "locked";

	@ConfigSection(
		name = "Lock icon",
		description = "The padlock drawn on locked slots.",
		position = 20
	)
	String iconSection = "icon";

	enum ShiftClickMode
	{
		PLACEHOLDER("Placeholder", "Placeholder"),
		ALL_BUT_ONE("Withdraw-All-but-1", "Withdraw-All-but-1"),
		OFF("Off", null);

		private final String label;
		/** The bank menu option to swap to, or null for no swap. */
		private final String option;

		ShiftClickMode(String label, String option)
		{
			this.label = label;
			this.option = option;
		}

		String getOption()
		{
			return option;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	enum IconPosition
	{
		// No top left: the stack size is drawn there.
		TOP_RIGHT("Top right"),
		BOTTOM_LEFT("Bottom left"),
		BOTTOM_RIGHT("Bottom right");

		private final String label;

		IconPosition(String label)
		{
			this.label = label;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	@ConfigItem(
		keyName = "shiftToToggle",
		name = "Shift to lock",
		description = "Only show Lock slot and Unlock slot in the menu while Shift is held.",
		position = 1
	)
	default boolean shiftToToggle()
	{
		return false;
	}

	@ConfigItem(
		keyName = "chatMessage",
		name = "Chat messages",
		description = "Show a chat message when an item is locked or unlocked, or an action is blocked.",
		position = 2
	)
	default boolean chatMessage()
	{
		return true;
	}

	@ConfigItem(
		keyName = "hideRelease",
		name = "Hide Release",
		description = "Remove Release from the menu of locked placeholders.",
		position = 1,
		section = lockedSection
	)
	default boolean hideRelease()
	{
		return true;
	}

	@ConfigItem(
		keyName = "blockWithdrawX",
		name = "Hide Withdraw-X",
		description = "Remove Withdraw-X from the menu of locked items when placeholders are off.",
		position = 2,
		section = lockedSection
	)
	default boolean blockWithdrawX()
	{
		return true;
	}

	@ConfigItem(
		keyName = "lockedShiftClick",
		name = "Shift-click",
		description = "What Shift-click Withdraw-All does on locked items when placeholders are off.",
		position = 3,
		section = lockedSection
	)
	default ShiftClickMode lockedShiftClick()
	{
		return ShiftClickMode.PLACEHOLDER;
	}

	@ConfigItem(
		keyName = "showIcon",
		name = "Show icon",
		description = "Draw a padlock on locked slots.",
		position = 1,
		section = iconSection
	)
	default boolean showIcon()
	{
		return true;
	}

	@Alpha
	@ConfigItem(
		keyName = "iconColor",
		name = "Color",
		description = "The color of the padlock.",
		position = 2,
		section = iconSection
	)
	default Color iconColor()
	{
		return new Color(255, 200, 0, 220);
	}

	@ConfigItem(
		keyName = "iconPosition",
		name = "Position",
		description = "Which corner of the slot the padlock is drawn in.",
		position = 3,
		section = iconSection
	)
	default IconPosition iconPosition()
	{
		return IconPosition.BOTTOM_LEFT;
	}

	@Range(min = 25, max = 200)
	@Units(Units.PERCENT)
	@ConfigItem(
		keyName = "iconScale",
		name = "Size",
		description = "The size of the padlock.",
		position = 4,
		section = iconSection
	)
	default int iconScale()
	{
		return 50;
	}
}

package com.bankslotlock;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.geom.AffineTransform;
import javax.inject.Inject;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.ui.overlay.WidgetItemOverlay;

/** Draws a small padlock in a corner of locked bank slots. */
class BankSlotLockOverlay extends WidgetItemOverlay
{
	/** Padlock size at 100% scale, in pixels. */
	private static final int ICON_WIDTH = 9;
	private static final int ICON_HEIGHT = 11;
	/** Gap between the padlock and the edge of the slot. */
	private static final int MARGIN = 1;
	/** How far the shadow sits below and to the right of the padlock, in screen pixels. */
	private static final int SHADOW_OFFSET = 1;

	private final BankSlotLockPlugin plugin;
	private final BankSlotLockConfig config;

	private final BasicStroke shackleStroke = new BasicStroke(1.5f);

	@Inject
	BankSlotLockOverlay(BankSlotLockPlugin plugin, BankSlotLockConfig config)
	{
		this.plugin = plugin;
		this.config = config;
		showOnBank();
	}

	@Override
	public void renderItemOverlay(Graphics2D g, int itemId, WidgetItem widgetItem)
	{
		if (!config.showIcon() || !plugin.isLocked(itemId))
		{
			return;
		}

		double scale = config.iconScale() / 100.0;
		double w = ICON_WIDTH * scale;
		double h = ICON_HEIGHT * scale;

		Rectangle b = widgetItem.getCanvasBounds();
		double x;
		double y;
		switch (config.iconPosition())
		{
			case TOP_RIGHT:
				x = b.x + b.width - w - MARGIN;
				y = b.y + MARGIN;
				break;
			case BOTTOM_RIGHT:
				x = b.x + b.width - w - MARGIN;
				y = b.y + b.height - h - MARGIN;
				break;
			case BOTTOM_LEFT:
			default:
				x = b.x + MARGIN;
				y = b.y + b.height - h - MARGIN;
				break;
		}

		Color color = config.iconColor();
		Color shadow = new Color(0, 0, 0, color.getAlpha());

		Object savedAa = g.getRenderingHint(RenderingHints.KEY_ANTIALIASING);
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		try
		{
			// Shadow 1 screen pixel down and right, like RuneLite's overlay text.
			drawPadlock(g, x + SHADOW_OFFSET, y + SHADOW_OFFSET, scale, shadow);
			drawPadlock(g, x, y, scale, color);
		}
		finally
		{
			if (savedAa != null)
			{
				g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, savedAa);
			}
		}
	}

	private void drawPadlock(Graphics2D g, double x, double y, double scale, Color color)
	{
		AffineTransform saved = g.getTransform();
		try
		{
			g.translate(x, y);
			g.scale(scale, scale);
			g.setColor(color);

			// Shackle
			g.setStroke(shackleStroke);
			g.drawArc(1, 0, 6, 7, 0, 180);
			g.drawLine(1, 3, 1, 5);
			g.drawLine(7, 3, 7, 5);
			// Body
			g.fillRect(0, 5, ICON_WIDTH, 6);
		}
		finally
		{
			g.setTransform(saved);
		}
	}
}

package com.bankslotlock;

import com.google.inject.Provides;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.Set;
import java.util.stream.Collectors;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.KeyCode;
import net.runelite.api.Menu;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.api.events.MenuOpened;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.PostMenuSort;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.RuneScapeProfileChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.JagexColors;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.ColorUtil;
import net.runelite.client.util.Text;

@Slf4j
@PluginDescriptor(
	name = "Bank Slot Lock",
	description = "Lock bank items so their placeholder can't be released and the slot can't be emptied by a withdraw",
	tags = {"bank", "placeholder", "lock", "release", "withdraw", "protect"}
)
public class BankSlotLockPlugin extends Plugin
{
	private static final String LOCK = "Lock slot";
	private static final String UNLOCK = "Unlock slot";
	/** Bank item op 1 is the left-click withdraw at the current quantity setting. */
	private static final int LEFT_CLICK_OP = 1;

	@Inject
	private Client client;

	@Inject
	private BankSlotLockConfig config;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ItemManager itemManager;

	@Inject
	private ChatMessageManager chatMessageManager;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private BankSlotLockOverlay overlay;

	/** Canonical (unnoted, non-placeholder) item IDs locked on the current account. */
	private Set<Integer> locked = Collections.emptySet();

	@Override
	protected void startUp()
	{
		loadLocks();
		overlayManager.add(overlay);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		locked = Collections.emptySet();
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		loadLocks();
	}

	boolean isLocked(int itemId)
	{
		return !locked.isEmpty() && locked.contains(itemManager.canonicalize(itemId));
	}

	@Subscribe
	public void onMenuOpened(MenuOpened event)
	{
		hideWithdrawAll(event.getMenuEntries());

		if (config.shiftToToggle() && !client.isKeyPressed(KeyCode.KC_SHIFT))
		{
			return;
		}

		for (MenuEntry entry : event.getMenuEntries())
		{
			Widget widget = bankItemWidget(entry);
			if (widget == null)
			{
				continue;
			}

			int canonical = itemManager.canonicalize(widget.getItemId());
			boolean isLocked = locked.contains(canonical);
			String name = itemManager.getItemComposition(canonical).getName();

			// MenuAction.RUNELITE entries are handled client-side only and send nothing to the server.
			client.getMenu().createMenuEntry(1)
				.setOption(isLocked ? UNLOCK : LOCK)
				.setTarget(ColorUtil.wrapWithColorTag(name, JagexColors.MENU_TARGET))
				.setType(MenuAction.RUNELITE)
				.onClick(e -> toggleLock(canonical, name));
			return;
		}
	}

	/**
	 * With placeholders off, turn a Shift-click Withdraw-All on a locked item into Placeholder
	 * (withdraw all, keep a placeholder) or Withdraw-All-but-1, depending on the setting.
	 * Runs after Menu Entry Swapper (lower priority) so it also catches MES's own shift-click swap.
	 */
	@Subscribe(priority = -1)
	public void onPostMenuSort(PostMenuSort event)
	{
		String swapTo = config.lockedShiftClick().getOption();
		if (swapTo == null
			|| client.isMenuOpen()
			|| !client.isKeyPressed(KeyCode.KC_SHIFT)
			|| client.getVarbitValue(VarbitID.BANK_LEAVEPLACEHOLDERS) == 1)
		{
			return;
		}

		Menu menu = client.getMenu();
		MenuEntry[] entries = menu.getMenuEntries();
		if (entries.length == 0)
		{
			return;
		}

		// The last entry is the left-click action.
		MenuEntry top = entries[entries.length - 1];
		Widget widget = bankItemWidget(top);
		if (widget == null
			|| !"Withdraw-All".equalsIgnoreCase(Text.removeTags(top.getOption()))
			|| !isLocked(widget.getItemId()))
		{
			return;
		}

		for (int i = entries.length - 2; i >= 0; i--)
		{
			MenuEntry entry = entries[i];
			if (entry.getParam1() == top.getParam1()
				&& entry.getParam0() == top.getParam0()
				&& swapTo.equalsIgnoreCase(Text.removeTags(entry.getOption())))
			{
				// Raise its priority so the client doesn't re-sort it below other ops.
				entry.setType(MenuAction.CC_OP);
				entries[i] = top;
				entries[entries.length - 1] = entry;
				menu.setMenuEntries(entries);
				return;
			}
		}
	}

	@Subscribe
	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		MenuEntry entry = event.getMenuEntry();
		String option = Text.removeTags(entry.getOption());
		boolean isRelease = "Release".equals(option);
		boolean isWithdraw = option.startsWith("Withdraw-");
		if (!isRelease && !isWithdraw)
		{
			return;
		}

		Widget widget = bankItemWidget(entry);
		if (widget == null || !isLocked(widget.getItemId()))
		{
			return;
		}

		if (isRelease)
		{
			if (config.hideRelease())
			{
				client.getMenu().removeMenuEntry(entry);
			}
			return;
		}

		if (shouldHideWithdraw(entry, option, widget.getItemQuantity()))
		{
			client.getMenu().removeMenuEntry(entry);
		}
	}

	/**
	 * With placeholders off, remove Withdraw-All from a locked item's right-click menu.
	 * Done when the menu opens rather than in onMenuEntryAdded, so the Shift-click
	 * All-but-1 swap can still find Withdraw-All while the left-click is being worked out.
	 */
	private void hideWithdrawAll(MenuEntry[] entries)
	{
		if (locked.isEmpty() || client.getVarbitValue(VarbitID.BANK_LEAVEPLACEHOLDERS) == 1)
		{
			return;
		}

		for (MenuEntry entry : entries)
		{
			if (entry.getIdentifier() == LEFT_CLICK_OP
				|| WithdrawAmount.parse(Text.removeTags(entry.getOption())) != WithdrawAmount.ALL)
			{
				continue;
			}

			Widget widget = bankItemWidget(entry);
			if (widget != null && isLocked(widget.getItemId()))
			{
				client.getMenu().removeMenuEntry(entry);
			}
		}
	}

	/**
	 * With placeholders off, hide Withdraw-X (if Hide Withdraw-X is on) and the remembered
	 * Withdraw-N entry when N would take the whole stack. Withdraw-All is hidden separately in
	 * onMenuOpened. Withdraw-1/5/10 and the left-click entry stay visible; clicking them is still
	 * blocked in onMenuOptionClicked.
	 */
	private boolean shouldHideWithdraw(MenuEntry entry, String option, int quantity)
	{
		if (client.getVarbitValue(VarbitID.BANK_LEAVEPLACEHOLDERS) == 1
			|| entry.getIdentifier() == LEFT_CLICK_OP)
		{
			return false;
		}

		int amount = WithdrawAmount.parse(option);
		if (amount == WithdrawAmount.UNKNOWN)
		{
			return config.blockWithdrawX();
		}
		return WithdrawAmount.isRememberedX(amount) && amount >= quantity;
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (locked.isEmpty() || event.getMenuAction() == MenuAction.RUNELITE)
		{
			return;
		}

		if (event.getParam1() == InterfaceID.Bankmain.RELEASE_PLACEHOLDERS)
		{
			String lockedPlaceholder = firstLockedPlaceholder();
			if (lockedPlaceholder != null)
			{
				event.consume();
				notifyBlocked("Release all placeholders blocked: " + lockedPlaceholder + " is locked.");
			}
			return;
		}

		Widget widget = bankItemWidget(event.getMenuEntry());
		if (widget == null || !isLocked(widget.getItemId()))
		{
			return;
		}

		String option = Text.removeTags(event.getMenuOption());
		String name = itemManager.getItemComposition(itemManager.canonicalize(widget.getItemId())).getName();

		if ("Release".equals(option))
		{
			event.consume();
			notifyBlocked(name + " is locked, so its placeholder can't be released.");
			return;
		}

		boolean placeholdersOn = client.getVarbitValue(VarbitID.BANK_LEAVEPLACEHOLDERS) == 1;
		if (placeholdersOn)
		{
			return;
		}

		int amount = WithdrawAmount.parse(option);
		if (WithdrawAmount.empties(amount, widget.getItemQuantity(), config.blockWithdrawX()))
		{
			event.consume();
			notifyBlocked(name + " is locked and placeholders are off, so " + option + " would empty its slot.");
		}
	}

	/** Returns the bank grid widget an entry belongs to, or null if it isn't a real bank item. */
	private Widget bankItemWidget(MenuEntry entry)
	{
		if (entry == null || entry.getParam1() != InterfaceID.Bankmain.ITEMS)
		{
			return null;
		}

		Widget widget = entry.getWidget();
		if (widget == null || widget.getItemId() <= 0)
		{
			return null;
		}
		return widget;
	}

	/** Name of a locked item currently sitting in the bank as a placeholder, or null. */
	private String firstLockedPlaceholder()
	{
		ItemContainer bank = client.getItemContainer(InventoryID.BANK);
		if (bank == null)
		{
			// Can't tell what's in the bank, so err on the side of keeping the placeholders.
			return "an item";
		}

		for (Item item : bank.getItems())
		{
			if (item.getId() <= 0)
			{
				continue;
			}

			ItemComposition comp = itemManager.getItemComposition(item.getId());
			if (comp.getPlaceholderTemplateId() != -1 && locked.contains(comp.getPlaceholderId()))
			{
				return itemManager.getItemComposition(comp.getPlaceholderId()).getName();
			}
		}
		return null;
	}

	private void toggleLock(int canonicalId, String name)
	{
		Set<Integer> next = new HashSet<>(locked);
		boolean nowLocked = next.add(canonicalId);
		if (!nowLocked)
		{
			next.remove(canonicalId);
		}
		locked = next;
		saveLocks();

		sendChat(name + (nowLocked ? " is now locked." : " is now unlocked."));
	}

	private void notifyBlocked(String message)
	{
		log.debug("Blocked: {}", message);
		sendChat(message);
	}

	private void sendChat(String message)
	{
		if (!config.chatMessage())
		{
			return;
		}

		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.GAMEMESSAGE)
			.runeLiteFormattedMessage(message)
			.build());
	}

	private void loadLocks()
	{
		String raw = configManager.getRSProfileConfiguration(BankSlotLockConfig.GROUP, BankSlotLockConfig.LOCKED_ITEMS_KEY);
		if (raw == null || raw.isEmpty())
		{
			locked = Collections.emptySet();
			return;
		}

		Set<Integer> ids = new HashSet<>();
		for (String part : raw.split(","))
		{
			try
			{
				ids.add(Integer.parseInt(part.trim()));
			}
			catch (NumberFormatException e)
			{
				log.debug("Skipping bad locked item id '{}'", part);
			}
		}
		locked = ids;
	}

	private void saveLocks()
	{
		if (locked.isEmpty())
		{
			configManager.unsetRSProfileConfiguration(BankSlotLockConfig.GROUP, BankSlotLockConfig.LOCKED_ITEMS_KEY);
			return;
		}

		String raw = locked.stream().sorted().map(String::valueOf).collect(Collectors.joining(","));
		configManager.setRSProfileConfiguration(BankSlotLockConfig.GROUP, BankSlotLockConfig.LOCKED_ITEMS_KEY, raw);
	}

	@Provides
	BankSlotLockConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(BankSlotLockConfig.class);
	}
}

package com.bankslotlock;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Works out how many items a bank menu option withdraws, from its text.
 */
final class WithdrawAmount
{
	/** The option is not a withdraw. */
	static final int NOT_WITHDRAW = -1;
	/** Withdraw-X: the amount is typed after the click, so it is unknown here. */
	static final int UNKNOWN = -2;
	/** Withdraw-All: always takes the whole stack. */
	static final int ALL = Integer.MAX_VALUE;
	/** Withdraw-All-but-1: never empties the slot. */
	static final int ALL_BUT_ONE = 0;

	private static final Pattern NUMBER = Pattern.compile("withdraw-(\\d+)");

	private WithdrawAmount()
	{
	}

	static int parse(String option)
	{
		if (option == null)
		{
			return NOT_WITHDRAW;
		}

		String o = option.trim().toLowerCase();
		if (!o.startsWith("withdraw-"))
		{
			return NOT_WITHDRAW;
		}
		if (o.equals("withdraw-all"))
		{
			return ALL;
		}
		if (o.equals("withdraw-all-but-1"))
		{
			return ALL_BUT_ONE;
		}
		if (o.equals("withdraw-x"))
		{
			return UNKNOWN;
		}

		Matcher m = NUMBER.matcher(o);
		if (m.matches())
		{
			try
			{
				return Integer.parseInt(m.group(1));
			}
			catch (NumberFormatException e)
			{
				return ALL;
			}
		}
		return UNKNOWN;
	}

	/**
	 * Whether a numeric withdraw is the remembered Withdraw-X amount rather than one of the
	 * game's fixed Withdraw-1/5/10 options.
	 */
	static boolean isRememberedX(int amount)
	{
		return amount > 0 && amount != ALL && amount != 1 && amount != 5 && amount != 10;
	}

	/**
	 * Whether this withdraw would leave the slot empty.
	 *
	 * @param amount   result of {@link #parse}
	 * @param quantity current stack size in the bank
	 * @param blockUnknown treat Withdraw-X as emptying
	 */
	static boolean empties(int amount, int quantity, boolean blockUnknown)
	{
		if (amount == NOT_WITHDRAW || amount == ALL_BUT_ONE)
		{
			return false;
		}
		if (amount == UNKNOWN)
		{
			return blockUnknown;
		}
		return amount >= quantity;
	}
}

package com.bankslotlock;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class BankSlotLockPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(BankSlotLockPlugin.class);
		RuneLite.main(args);
	}
}

package com.bankslotlock;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class WithdrawAmountTest
{
	@Test
	public void parsesOptions()
	{
		assertEquals(1, WithdrawAmount.parse("Withdraw-1"));
		assertEquals(28, WithdrawAmount.parse("Withdraw-28"));
		assertEquals(WithdrawAmount.ALL, WithdrawAmount.parse("Withdraw-All"));
		assertEquals(WithdrawAmount.ALL_BUT_ONE, WithdrawAmount.parse("Withdraw-All-but-1"));
		assertEquals(WithdrawAmount.UNKNOWN, WithdrawAmount.parse("Withdraw-X"));
		assertEquals(WithdrawAmount.NOT_WITHDRAW, WithdrawAmount.parse("Examine"));
		assertEquals(WithdrawAmount.NOT_WITHDRAW, WithdrawAmount.parse("Release"));
		assertEquals(WithdrawAmount.NOT_WITHDRAW, WithdrawAmount.parse(null));
	}

	@Test
	public void recognisesRememberedX()
	{
		assertTrue(WithdrawAmount.isRememberedX(28));
		assertTrue(WithdrawAmount.isRememberedX(2));
		assertFalse(WithdrawAmount.isRememberedX(1));
		assertFalse(WithdrawAmount.isRememberedX(5));
		assertFalse(WithdrawAmount.isRememberedX(10));
		assertFalse(WithdrawAmount.isRememberedX(WithdrawAmount.ALL));
		assertFalse(WithdrawAmount.isRememberedX(WithdrawAmount.ALL_BUT_ONE));
		assertFalse(WithdrawAmount.isRememberedX(WithdrawAmount.UNKNOWN));
	}

	@Test
	public void decidesWhetherSlotEmpties()
	{
		assertTrue(WithdrawAmount.empties(1, 1, false));
		assertFalse(WithdrawAmount.empties(1, 2, false));
		assertTrue(WithdrawAmount.empties(10, 5, false));
		assertTrue(WithdrawAmount.empties(WithdrawAmount.ALL, 1000, false));
		assertFalse(WithdrawAmount.empties(WithdrawAmount.ALL_BUT_ONE, 1, true));
		assertTrue(WithdrawAmount.empties(WithdrawAmount.UNKNOWN, 1000, true));
		assertFalse(WithdrawAmount.empties(WithdrawAmount.UNKNOWN, 1000, false));
		assertFalse(WithdrawAmount.empties(WithdrawAmount.NOT_WITHDRAW, 1, true));
	}
